import{_ as t,c as o,o as r,a0 as i}from"./chunks/framework.oTSD2LDJ.js";const m=JSON.parse('{"title":"About Uniquenium","description":"","frontmatter":{"title":"About Uniquenium","layout":"doc","editLink":true},"headers":[],"relativePath":"en/about.md","filePath":"en/about.md"}'),n={name:"en/about.md"};function a(s,e,l,u,d,c){return r(),o("div",null,e[0]||(e[0]=[i(`<h1 id="about-uniquenium" tabindex="-1">About Uniquenium <a class="header-anchor" href="#about-uniquenium" aria-label="Permalink to &quot;About Uniquenium&quot;">​</a></h1><h2 id="project-introduction" tabindex="-1">Project Introduction <a class="header-anchor" href="#project-introduction" aria-label="Permalink to &quot;Project Introduction&quot;">​</a></h2><p><strong>Uniquenium</strong> is an open-source desktop customization tool dedicated to a customizable desktop environment. The project name combines &quot;Unique&quot; + &quot;Quantum,&quot; signifying the creation of a one-of-a-kind desktop experience for every user.</p><p>We believe the desktop is more than just a starting point for work — it is a canvas for expressing individuality.</p><ul><li>🎨 <strong>Beautiful</strong>: Modern Fluent design language, seamless dark/light theme switching</li><li>🧩 <strong>Flexible</strong>: Component-based architecture, mix and match your desktop exactly how you want</li><li>🔌 <strong>Open</strong>: Plugin and template system, infinite extension possibilities</li><li>💝 <strong>Free</strong>: Fully open-source and free of charge, community-driven development</li></ul><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2><ul><li><a href="https://github.com/admibrill" target="_blank" rel="noreferrer">Admibrill</a></li></ul><p>From the initial simple panel prototype to today&#39;s mature project with a complete control library, plugin system and templating mechanism — none of this would have been possible without the effort of every contributor.</p><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th><th>Description</th></tr></thead><tbody><tr><td>Interface Rendering</td><td><strong>QML / Qt Quick</strong></td><td>Declarative UI language, hardware-accelerated rendering</td></tr><tr><td>Core Logic</td><td><strong>C++17 / Qt6</strong></td><td>Pure C++ implementation, high performance and cross-platform</td></tr><tr><td>UI Control Library</td><td><strong>UniDesk</strong></td><td>Self-developed 30+ controls, based on LingmoUI design</td></tr><tr><td>System Interaction</td><td><strong>Win32 API / QHotkey</strong></td><td>Frameless windows, global hotkeys, wallpaper setting, etc.</td></tr><tr><td>Build System</td><td><strong>CMake + ECM</strong></td><td>Cross-platform compilation and packaging</td></tr><tr><td>Documentation Site</td><td><strong>VitePress</strong></td><td>Vue-based static site generator</td></tr><tr><td>Icon Resources</td><td><strong>Remix Icons</strong></td><td>Open-source neutral-style icon library</td></tr></tbody></table><h2 id="acknowledgments" tabindex="-1">Acknowledgments <a class="header-anchor" href="#acknowledgments" aria-label="Permalink to &quot;Acknowledgments&quot;">​</a></h2><p>Uniquenium would not exist without the support of the following open-source projects and individuals:</p><h3 id="core-contributors" tabindex="-1">Core Contributors <a class="header-anchor" href="#core-contributors" aria-label="Permalink to &quot;Core Contributors&quot;">​</a></h3><ul><li>💻 <a href="https://github.com/admibrill" target="_blank" rel="noreferrer">Admibrill</a> - Project initiator and core developer</li></ul><h3 id="open-source-projects" tabindex="-1">Open-Source Projects <a class="header-anchor" href="#open-source-projects" aria-label="Permalink to &quot;Open-Source Projects&quot;">​</a></h3><ul><li>🎨 <a href="https://github.com/LingmoOS/LingmoUI" target="_blank" rel="noreferrer">LingmoUI</a> - Design foundation for the UniDesk control library</li><li>⌨️ <a href="https://github.com/Skycoder42/QHotkey" target="_blank" rel="noreferrer">QHotkey</a> - Cross-platform global hotkey support</li><li>🔤 <a href="https://www.remixicon.cn" target="_blank" rel="noreferrer">Remix Icons</a> - Beautiful open-source icon library</li><li>🔢 <a href="https://github.com/ArashPartow/exprtk" target="_blank" rel="noreferrer">ExprTk</a> - Mathematical expression parsing engine</li><li>⚡ <a href="https://www.qt.io/" target="_blank" rel="noreferrer">Qt6</a> - Powerful cross-platform C++ application framework</li><li>📦 <a href="https://invent.kde.org/frameworks/extra-cmake-modules" target="_blank" rel="noreferrer">ECM</a> - Extra CMake Modules</li></ul><h3 id="community-users" tabindex="-1">Community &amp; Users <a class="header-anchor" href="#community-users" aria-label="Permalink to &quot;Community &amp; Users&quot;">​</a></h3><p>Thanks to every community member who submits Issues, PRs, translates documentation, and shares templates ❤️</p><p>QQ Group: 1107749494 Discord: <a href="https://discord.gg/Cqq9sRkrW2" target="_blank" rel="noreferrer">Uniquenium</a></p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><h3 id="code-license" tabindex="-1">Code License <a class="header-anchor" href="#code-license" aria-label="Permalink to &quot;Code License&quot;">​</a></h3><p>The Uniquenium project code is released under the <strong>GNU General Public License v3.0</strong> open-source agreement:</p><blockquote><p>You are free to run, study, share, and improve this software. Modified derivative works <strong>must</strong> also be open-sourced under the same license.</p></blockquote><p>Full license text: <a href="https://github.com/Uniquenium/Uniquenium/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a></p><h3 id="documentation-license" tabindex="-1">Documentation License <a class="header-anchor" href="#documentation-license" aria-label="Permalink to &quot;Documentation License&quot;">​</a></h3><p>This documentation (Docs repository) is licensed under the <strong>Creative Commons Attribution-ShareAlike 4.0 International (CC BY-SA 4.0)</strong> agreement:</p><blockquote><p>You may freely share (copy, distribute, transmit) and adapt (modify, commercial use) this documentation, provided that:</p><ul><li><strong>Attribution</strong>: Give appropriate credit, provide a link to the license</li><li><strong>Share Alike</strong>: Adapted content must be released under the same license</li></ul></blockquote><h2 id="version-information" tabindex="-1">Version Information <a class="header-anchor" href="#version-information" aria-label="Permalink to &quot;Version Information&quot;">​</a></h2><p>You can view the version in the following ways:</p><ul><li><strong>In the program</strong>: Settings → About → Version number</li><li><strong>In code</strong>:<div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> UniDesk</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Get version number through UniDeskTools</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var major = UniDeskTools.getModuleVersionMajor()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var minor = UniDeskTools.getModuleVersionMinor()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var patch = UniDeskTools.getModuleVersionPatch()</span></span></code></pre></div></li></ul><h2 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Link</th><th>Purpose</th></tr></thead><tbody><tr><td>GitHub Repository</td><td><a href="https://github.com/Uniquenium/Uniquenium" target="_blank" rel="noreferrer">Uniquenium/Uniquenium</a></td><td>Source code, Issues, PRs</td></tr><tr><td>Documentation Repository</td><td><a href="https://github.com/Uniquenium/Docs" target="_blank" rel="noreferrer">Uniquenium/Docs</a></td><td>This site&#39;s documentation source</td></tr><tr><td>DeepWiki</td><td><a href="https://deepwiki.com/Uniquenium/Uniquenium" target="_blank" rel="noreferrer">deepwiki.com/Uniquenium</a></td><td>Interactive code documentation</td></tr><tr><td>Issue Tracker</td><td><a href="https://github.com/Uniquenium/Uniquenium/issues/new/choose" target="_blank" rel="noreferrer">New Issue</a></td><td>Bug reports / Feature suggestions</td></tr></tbody></table><h2 id="contribution-guidelines" tabindex="-1">Contribution Guidelines <a class="header-anchor" href="#contribution-guidelines" aria-label="Permalink to &quot;Contribution Guidelines&quot;">​</a></h2><p>We warmly welcome contributions of all forms!</p><h3 id="ways-for-beginners-to-contribute" tabindex="-1">Ways for Beginners to Contribute <a class="header-anchor" href="#ways-for-beginners-to-contribute" aria-label="Permalink to &quot;Ways for Beginners to Contribute&quot;">​</a></h3><ol><li>📝 <strong>Improve Documentation</strong>: Fix typos, add clarifications, translate English docs</li><li>🐛 <strong>Report Bugs</strong>: Submit detailed reproduction steps and environment information</li><li>🎨 <strong>Share Templates</strong>: Export your beautifully designed page templates for others to use</li><li>💡 <strong>Share Suggestions</strong>: Share your usage experience and improvement ideas</li></ol><h3 id="code-contribution-process" tabindex="-1">Code Contribution Process <a class="header-anchor" href="#code-contribution-process" aria-label="Permalink to &quot;Code Contribution Process&quot;">​</a></h3><ol><li>Fork the repository to your account</li><li>Create a new branch: <code>git checkout -b feature/your-feature</code></li><li>Commit your code: <code>git commit -m &quot;feat: add your feature&quot;</code></li><li>Push the branch: <code>git push origin feature/your-feature</code></li><li>Open a Pull Request and wait for code review</li></ol><h3 id="commit-conventions" tabindex="-1">Commit Conventions <a class="header-anchor" href="#commit-conventions" aria-label="Permalink to &quot;Commit Conventions&quot;">​</a></h3><ul><li>feat: New feature</li><li>fix: Bug fix</li><li>docs: Documentation update</li><li>style: Code formatting (no functional change)</li><li>refactor: Refactoring</li><li>perf: Performance optimization</li><li>test: Testing related</li><li>chore: Build/toolchain related</li></ul><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><p>Want to know what we&#39;re working on? Check out the public <a href="https://github.com/Uniquenium/Uniquenium/blob/main/TODO.md" target="_blank" rel="noreferrer">Main Program TODO List</a> and <a href="https://github.com/Uniquenium/OfficialPlugin/blob/main/TODO.md" target="_blank" rel="noreferrer">Plugin TODO List</a>, including:</p><ul><li>✅ Linux platform support (in development)</li><li>✅ More official plugin components (calculator, screenshot, weather, etc.)</li></ul><hr><p><strong>Made with ❤️ by Uniquenium Development Team</strong></p><blockquote><p>「Let the desktop return to how you want it to be.」</p></blockquote>`,46)]))}const p=t(n,[["render",a]]);export{m as __pageData,p as default};
